ValidationRule.errorConditionFormula:
AND( NOT( $Setup.PMC_ProcessSwitches__c.PMC_BypassValidationRule__c ),
NOT( OR( BEGINS(Profile.Name, 'Digital Hub'),(Profile.Name == 'API Only profile'), (Profile.Name == 'Partner Community User') ) ), OR( ISBLANK( FederationIdentifier ), ISBLANK( MobilePhone ), ISBLANK( TEXT(PMC_CPQ_SalesRegion__c) ) )
)
